\begin{aligned}
P(G=1|D=1) 
    &= \frac{P(G = 1, D = 1)}{P(D=1)} \\
    && \text{Cond. Prob.}\\
    &= \frac{P(G = 1, D = 1, T= 0) + P(G=1, D = 1, T=1)}{P(D=1)} \\
    && \text{Prob or}\\
    &= \frac{0.01 + 0.08}{0.12} = 0.75
    && \text{From joint}
\end{aligned}

\begin{aligned}
P(G=1|D=0) 
    &= \frac{P(G = 1, D = 0)}{P(D=0)} \\
    && \text{Cond. Prob.}\\
    &= \frac{P(G = 1, D = 0, T= 0) + P(G=1, D = 0, T=1)}{P(D=0)} \\
    && \text{Prob or}\\
    &= \frac{0.32 + 0.28}{0.88} \approx 0.68
    && \text{From joint}
\end{aligned}
